import hashlib, json, re
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import parse_qs, urlsplit

class QuoteSections(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.section = None
        self.depth = 0
        self.sections = []

    def handle_starttag(self, tag, attrs):
        if tag == 'section':
            if self.depth == 0:
                self.section = {'text': [], 'links': []}
            self.depth += 1
        if self.section is not None and tag == 'a':
            self.section['links'].append(dict(attrs).get('href', ''))

    def handle_endtag(self, tag):
        if tag == 'section' and self.depth:
            self.depth -= 1
            if self.depth == 0:
                self.sections.append(self.section)
                self.section = None

    def handle_data(self, data):
        if self.section is not None:
            self.section['text'].append(data)

path = Path('products/sites/sqlite-statement-diagnostic/index.html')
raw = path.read_bytes()
sha = hashlib.sha256(raw).hexdigest()
parser = QuoteSections()
parser.feed(raw.decode('utf-8'))
results = {}
for language, heading, intent in [('en', 'Request a private quote', 'request a nonbinding private quote'), ('fr', 'Demander un devis privé', 'demander un devis privé sans engagement')]:
    matches = [section for section in parser.sections if heading in ''.join(section['text'])]
    checks = []
    for section in matches:
        text = ''.join(section['text'])
        mail_links = []
        for href in section['links']:
            url = urlsplit(href)
            if url.scheme != 'mailto':
                continue
            query = parse_qs(url.query)
            subject = query.get('subject', [''])[0]
            body = query.get('body', [''])[0]
            mail_links.append({'public_recipient_matches': url.path == 'globalland@agentmail.to', 'subject_matches': subject == 'site:sqlite-statement-diagnostic interest', 'body_has_experiment_line': 'Experiment: site:sqlite-statement-diagnostic' in body.splitlines(), 'body_has_quote_intent': intent in body, 'body_has_separate_sql_fields': {'seed_sql:', 'query_sql:'}.issubset(set(body.splitlines()))})
        checks.append({'mailto': mail_links, 'manual_subject_present': 'site:sqlite-statement-diagnostic interest' in text, 'manual_sql_fields_present': {'seed_sql:', 'query_sql:'}.issubset(set(text.splitlines())), 'manual_quote_intent_present': intent in text, 'visible_copy_ends_in_fragment': bool(re.search(r'\bpersona\s*$', next((part for part in section['text'] if 'synthetic or anonymized' in part), '')))})
    results[language] = {'matching_sections': len(matches), 'sections': checks}
report = {'input': str(path), 'sha256': sha, 'matches_restoration_receipt': sha == 'f71bdac2fe5c9623bdbf65626d968008e846414e1cea8912cc42633e3d155fb5', 'checks': results, 'scope': 'Offline inspection of the staged quote form. This establishes neither mail client behavior nor live intake, orders or settlement.'}
out = Path('products/distribution/sqlite-instructor-pilot/reconciliation/private-quote-intake-static-check.json')
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text(json.dumps(report, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(out.read_text(encoding='utf-8'))
